    "flowchart": {
      "curve": "curve"
    }
  }
}%%
graph LR
  BRIEF["User brief"]
  COORD["Deep Agents coordinator"]
  PANELS["Stripe / PostHog / GitHub / Calendar panel agents"]
  SUBAGENTS["stream.subagents"]
  RENDERER["Renderer per panel"]

  BRIEF --> COORD
  COORD --"parallel task() calls"--> PANELS
